def se_date_pattern():
    return r'(?:\d{4}-\d{2}-\d{2}|(?:January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\s+\d{1,2}(?:st|nd|rd|th)?(?:,)?\s+\d{4})'

def se_normalize_date(value):
    value = value.strip()
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}', value):
        return value
    match = re.fullmatch(r'([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,)?\s+(\d{4})', value)
    if match is None:
        return None
    months = {'jan':'01','feb':'02','mar':'03','apr':'04','may':'05','jun':'06','jul':'07','aug':'08','sep':'09','oct':'10','nov':'11','dec':'12'}
    month = months.get(match.group(1).lower()[:3])
    if month is None:
        return None
    return match.group(3) + '-' + month + '-' + match.group(2).zfill(2)

def se_person_pattern():
    return r'[A-Z][A-Za-z\'’\-]*(?:\s+[A-Z][A-Za-z\'’\-]*){0,3}'

def se_sentences(text):
    result = []
    for match in re.finditer(r'[^.!?]+[.!?]?', text):
        value = match.group(0).strip()
        if value:
            result.append(value)
    return result

def se_people(value):
    result = []
    cleaned = re.sub(r'\s+', ' ', value.strip())
    for item in re.split(r'\s*,\s*|\s+and\s+', cleaned):
        person = item.strip()
        if person and re.fullmatch(se_person_pattern(), person) and person not in result:
            result.append(person)
    return result

def se_payees(value):
    result = []
    pattern = r'\bto\s+(' + se_person_pattern() + r')\b'
    for match in re.finditer(pattern, value):
        person = match.group(1).strip()
        if person not in result:
            result.append(person)
    return result

def se_service_match(text):
    return re.search(r'\bfor\s+(agricultural\s+labor|domestic\s+service|services?|work|labor)\b', text, re.I)

def se_kind(term):
    value = re.sub(r'\s+', ' ', term.lower()).strip()
    if value in ('agricultural labor', 'domestic service', 'service', 'services', 'work', 'labor'):
        return value
    return None

def se_time(text, position):
    tail = text[position:]
    date = se_date_pattern()
    ranges = list(re.finditer(r'\bfrom\s+(' + date + r')\s+(?:to|through|until)\s+(' + date + r')', tail, re.I))
    ranges += list(re.finditer(r'\bbetween\s+(' + date + r')\s+and\s+(' + date + r')', tail, re.I))
    if len(ranges) > 1:
        return None
    if len(ranges) == 1:
        start = se_normalize_date(ranges[0].group(1))
        end = se_normalize_date(ranges[0].group(2))
        if start is None or end is None:
            return None
        return {'period_form':'closed_interval','start_date':start,'end_date':end,'service_year':None}
    dates = list(re.finditer(r'\b(?:on|performed\s+on|done\s+on)\s+(' + date + r')', tail, re.I))
    if len(dates) > 1:
        return None
    if len(dates) == 1:
        day = se_normalize_date(dates[0].group(1))
        if day is None:
            return None
        return {'period_form':'on_date','start_date':day,'end_date':day,'service_year':None}
    years = list(re.finditer(r'\b(?:during|throughout|in)\s+((?:19|20)\d{2})\b', tail, re.I))
    if len(years) > 1:
        return None
    if len(years) == 1:
        return {'period_form':'year_only','start_date':None,'end_date':None,'service_year':int(years[0].group(1))}
    if re.search(date, tail, re.I):
        return None
    return {'period_form':'unstated','start_date':None,'end_date':None,'service_year':None}

def se_place(text, position):
    tail = text[position:]
    venues = ('private home','local college club','local chapter of a college fraternity','local chapter of a college sorority')
    venue = None
    for item in venues:
        if re.search(r'\b' + re.escape(item) + r'\b', tail, re.I):
