    if employer_match is None:
        by_match = re.search(r'\bpaid\s+by\s+(.+?)(?=\s+for\s+)', body, re.I)
        employer = se_clean_entity(by_match.group(1)) if by_match is not None else None
    else:
        employer = se_clean_entity(employer_match.group(1))
