def se_direct(body, quote, rows):
    pattern = r'\b(' + se_person_pattern() + r')\s+(?:performed|provided|did|worked)\s+(agricultural\s+labor|domestic\s+service|services?|work|labor)\s+for\s+(.+?)(?=\s+from\b|\s+between\b|\s+on\b|\s+during\b|\s+throughout\b|$)'
