        name = match.group(1).strip()
        if name not in result:
            result.append(name)
    return result

def sr_service_clause(text):
    return re.search(r'\bfor\s+(agricultural\s+labor|domestic\s+service|services?|work|labor)\b', text, re.I)

def sr_period(text, anchor):
    tail = text[anchor:]
    date = sr_date_pattern()
    spans = list(re.finditer(r'\bfrom\s+(' + date + r')\s+(?:to|through|until)\s+(' + date + r')', tail, re.I))
    spans += list(re.finditer(r'\bbetween\s+(' + date + r')\s+and\s+(' + date + r')', tail, re.I))
    if len(spans) > 1:
        return None
    if len(spans) == 1:
        start = sr_date(spans[0].group(1))
        end = sr_date(spans[0].group(2))
        if start is None or end is None:
            return None
        return {'status':'interval','start':start,'end':end,'year':None}
    days = list(re.finditer(r'\b(?:on|performed\s+on|done\s+on)\s+(' + date + r')', tail, re.I))
    if len(days) > 1:
        return None
    if len(days) == 1:
        day = sr_date(days[0].group(1))
        if day is None:
            return None
        return {'status':'date','start':day,'end':day,'year':None}
    years = list(re.finditer(r'\b(?:during|throughout|in)\s+((?:19|20)\d{2})\b', tail, re.I))
    if len(years) > 1:
        return None
    if len(years) == 1:
        return {'status':'year_only','start':None,'end':None,'year':int(years[0].group(1))}
    if re.search(date, tail, re.I):
        return None
    return {'status':'not_stated','start':None,'end':None,'year':None}

def sr_places(text, anchor):
    tail = text[anchor:]
    venue = None
    for item in ('private home','local college club','local chapter of a college fraternity','local chapter of a college sorority'):
        if re.search(r'\b' + re.escape(item) + r'\b', tail, re.I):
            if venue is not None and venue != item:
                return None
            venue = item
    location = None
    country = None
    match = re.search(r'\b(?:performed|done|provided)\s+in\s+([A-Z][A-Za-z0-9 .\'’&\-]*(?:,\s*[A-Z][A-Za-z .\'’\-]*)?)\s+for\s+', tail)
    if match is not None:
        location = match.group(1).strip()
        pieces = location.split(',')
        if len(pieces) == 2 and pieces[1].strip():
            country = pieces[1].strip()
    return {'venue':venue,'geographic_location':location,'country':country}

def sr_entity(text):
    value = re.sub(r'\s+', ' ', text.strip(' ,;'))
    if value.lower().startswith('the '):
        value = value[4:].strip()
    return value if value else None

def sr_kind(term):
    value = re.sub(r'\s+', ' ', term.lower()).strip()
    return value if value in ('agricultural labor','domestic service','service','services','work','labor') else None

def sr_append(rows, workers, employer, grammar, term, period, places, quote):
    record = {'relation_id':'service_relation_' + str(len(rows)),'workers':workers,'employer':employer,'grammar':grammar,'service_term':term,'kind':sr_kind(term),'venue':places.get('venue'),'geographic_location':places.get('geographic_location'),'country':places.get('country'),'period':period,'witnesses':[{'field':'facts','quote':quote}]}
    key = (tuple(workers), employer, grammar, sr_kind(term), period.get('status'), period.get('start'), period.get('end'), period.get('year'), quote)
    for old in rows:
        old_period = old.get('period')
        old_key = (tuple(old.get('workers')), old.get('employer'), old.get('grammar'), old.get('kind'), old_period.get('status'), old_period.get('start'), old_period.get('end'), old_period.get('year'), old.get('witnesses')[0].get('quote'))
        if key == old_key:
            return
    rows.append(record)

def sr_read_active(body, quote, rows):
    paid = re.search(r'\b(' + sr_person_pattern() + r')\s+(?:has\s+|had\s+)?paid\b', body)
    service = sr_service_clause(body)
    if paid is None or service is None or paid.start() > service.start():
        return False
    workers = sr_to_workers(body[paid.end():service.start()])
    period = sr_period(body, service.start())
    places = sr_places(body, service.start())
    if len(workers) == 0 or period is None or places is None:
        return False
    sr_append(rows, workers, paid.group(1).strip(), 'active_remuneration', service.group(1), period, places, quote)
    return True

def sr_read_passive(body, quote, rows):
    paid = re.match(r'^(.+?)\s+(?:was|were|has\s+been|have\s+been|had\s+been)\s+paid\b', body, re.I)
    service = sr_service_clause(body)
    if paid is None or service is None or paid.end() > service.start():
        return False
    workers = sr_name_list(paid.group(1))
    local = body[service.start():]
    employer_match = re.search(r'\bfor\s+' + re.escape(service.group(1)) + r'\s+(?:performed|done|provided)\s+for\s+(.+?)(?=\s+from\b|\s+between\b|\s+on\b|\s+during\b|\s+throughout\b|$)', local, re.I)
    employer = sr_entity(employer_match.group(1)) if employer_match is not None else None
    if employer is None:
        by_match = re.search(r'\bpaid\s+by\s+(.+?)(?=\s+for\s+)', body, re.I)
        employer = sr_entity(by_match.group(1)) if by_match is not None else None
    period = sr_period(body, service.start())
    places = sr_places(body, service.start())
    if len(workers) == 0 or employer is None or period is None or places is None:
        return False
    sr_append(rows, workers, employer, 'passive_remuneration', service.group(1), period, places, quote)
    return True

def sr_read_direct(body, quote, rows):
    pattern = r'\b(' + sr_person_pattern() + r')\s+(?:performed|provided|did|worked)\s+(agricultural\s+labor|domestic\s+service|services?|work|labor)\s+for\s+(.+?)(?=\s+from\b|\s+between\b|\s+on\b|\s+during\b|\s+throughout\b|$)'
    match = re.search(pattern, body, re.I)
    if match is None:
        return False
    employer = sr_entity(match.group(3))
    period = sr_period(body, match.start(2))
    places = sr_places(body, match.start(2))
    if employer is None or period is None or places is None:
        return False
    sr_append(rows, [match.group(1).strip()], employer, 'direct_service', match.group(2), period, places, quote)
    return True

def apply(inputs, premises):
    facts = inputs.get('facts') if type(inputs) is dict else None
    if type(facts) is not str or not facts:
        return {'views':[{'extraction_status':'unread','service_relations':None,'witnesses':[]}]}
    relations = []
    ambiguous = False
    cue = r'\b(?:services?|work|worked|labor|employ(?:ed|ment)|performed|provided)\b'
    for sentence in sr_sentences(facts):
        body = sentence.rstrip('.!?').strip()
        relevant = re.search(cue, body, re.I) is not None
        before = len(relations)
        handled = sr_read_active(body, sentence, relations)
        if not handled:
            handled = sr_read_passive(body, sentence, relations)
        if not handled:
            handled = sr_read_direct(body, sentence, relations)
        if relevant and (not handled or len(relations) == before):
            ambiguous = True
    witness = [{'field':'facts','quote':facts}]
    if ambiguous:
        return {'views':[{'extraction_status':'unread','service_relations':None,'witnesses':witness}]}
    return {'views':[{'extraction_status':'complete','service_relations':relations,'witnesses':witness}]}
